const isAllSites = (code: string) => code === 'ALL';

function leadInitials(name?: string) {
  if (!name) return '';
  const parts = name.replace(/[()]/g, ' ').split(/\s+/).filter(Boolean);
  if (!parts.length) return '';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function LeadAvatar({ name, photo }: { name?: string; photo?: string }) {
  if (photo) {
    return <img src={photo} alt="" className="size-14 shrink-0 rounded-full object-cover ring-1 ring-black/10" />;
  }
  return (
    <div className="flex size-14 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-black text-muted-foreground">
      {leadInitials(name)}
    </div>
  );
}

function pinClass(side: GeoSite['label']) {
  if (side === 'left') return 'right-full mr-1.5 translate-y-[-50%] text-right';
  if (side === 'right') return 'left-full ml-1.5 translate-y-[-50%] text-left';
  if (side === 'top') return 'bottom-full mb-1.5 left-1/2 -translate-x-1/2 text-center';
  return 'top-full mt-1.5 left-1/2 -translate-x-1/2 text-center';
}

function WorldLand({ fill = '#b0b5be' }: { fill?: string }) {
  return <path fill={fill} d={WORLD_PATH} />;
}

function WorldMapSvg({ viewBox, children }: { viewBox?: string; children?: ReactNode }) {
  return (
    <svg viewBox={viewBox ?? `0 0 ${MAP_W} ${MAP_H}`} className="h-full w-full" preserveAspectRatio="xMidYMid meet" aria-hidden="true">
      <rect width={MAP_W} height={MAP_H} fill="#ffffff" />
      <WorldLand />
      {children}
    </svg>
  );
}

function NetworkMap({ selected, onSelectSite }: { selected?: string; onSelectSite: (code: string) => void }) {
  return (
    <div className="relative mx-auto w-full max-w-5xl">
      <div className="relative w-full" style={{ paddingBottom: '58.4%' }}>
        <div className="absolute inset-0">
          <WorldMapSvg />
        </div>
        {geoSites.map((site: GeoSite) => {
          const active = selected === site.code;
          return (
            <button
              key={site.code}
              type="button"
              title={`${site.name} · ${site.code}`}
              onClick={() => onSelectSite(site.code)}
              className="absolute z-10 -translate-x-1/2 -translate-y-1/2"
              style={{ left: `${site.mx}%`, top: `${site.my}%` }}
            >
              <span
                className="block size-2.5 rounded-full ring-2 ring-white shadow"
                style={{ background: active ? '#ffffff' : regionColor[site.region], outline: active ? '2px solid #a3251b' : 'none' }}
              />
              <span className={`absolute whitespace-nowrap text-[9px] font-black leading-none ${active ? 'text-[var(--takeda-red)]' : 'text-[#102033]'} ${pinClass(site.label)}`}>
                {site.code}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function SiteGeoPicture({ site, onSelectSite }: { site: GeoSite; onSelectSite: (code: string) => void }) {
  const photo = plantPhotos[site.code];
  const cx = (site.mx / 100) * MAP_W;
  const cy = (site.my / 100) * MAP_H;
  const vw = 168;
  const vh = 86;
  return (
    <div className="relative h-56 overflow-hidden bg-[#1b2430]">
      {photo ? (
        <img src={photo} alt="" className="absolute inset-0 h-full w-full object-cover" />
      ) : (
        <div className="absolute inset-0">
          <WorldMapSvg viewBox={`${cx - vw / 2} ${cy - vh / 2} ${vw} ${vh}`}>
            <circle cx={cx} cy={cy} r="3.2" fill="#a3251b" stroke="#ffffff" strokeWidth="1.4" />
          </WorldMapSvg>
        </div>
      )}
      <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-black/25" />
      <div className="absolute inset-x-0 bottom-0 px-5 pb-3 pt-10 text-white">
        <p className="text-[10px] font-bold uppercase tracking-[0.14em]">{site.country ?? site.region}{site.reportsTo ? ` · reports to ${site.reportsTo}` : ''}</p>
        <h2 className="text-2xl font-black">{site.name} · {site.code}</h2>
      </div>
      <button type="button" className="absolute right-4 top-4 rounded-full bg-white/90 px-3 py-1 text-[10px] font-black text-[#102033]" onClick={() => onSelectSite('ALL')}>
        All sites map
      </button>
    </div>
  );
}

export function SiteLeadershipStrip({ code }: { code: string }) {
  if (isAllSites(code)) return null;
  const lead = siteLeadership[code] ?? {};
  const photos = peoplePhotos[code] ?? {};
  const missing = 'Not listed on Org Explorer';
  return (
    <section className="rounded-2xl border bg-card px-5 py-4 text-card-foreground shadow-sm">
      <div className="grid gap-4 sm:grid-cols-2">
        <div className="flex items-center gap-3">
          <LeadAvatar name={lead.manufacturingHead} photo={photos.mfg} />
          <div className="min-w-0">
            <p className="text-[10px] font-bold uppercase tracking-[0.14em] myc-muted">Site manufacturing head</p>
            <p className="text-lg font-black leading-tight">{lead.manufacturingHead ?? missing}</p>
            {lead.manufacturingTitle ? <p className="text-xs text-muted-foreground">{lead.manufacturingTitle}</p> : null}
          </div>
        </div>
        <div className="flex items-center gap-3">
          <LeadAvatar name={lead.qualityHead} photo={photos.qh} />
          <div className="min-w-0">
            <p className="text-[10px] font-bold uppercase tracking-[0.14em] myc-muted">Site quality head</p>
            <p className="text-lg font-black leading-tight">{lead.qualityHead ?? missing}</p>
            {lead.qualityTitle ? <p className="text-xs text-muted-foreground">{lead.qualityTitle}</p> : null}
          </div>
        </div>
      </div>
    </section>
  );
}

export function SiteNetworkHero({ site, onSelectSite }: { site: NetworkSite; onSelectSite: (code: string) => void }) {
  const current = geoSites.find((item: GeoSite) => item.code === site.code);
  const all = isAllSites(site.code);
  return (
    <section className="overflow-hidden rounded-2xl border bg-card text-card-foreground shadow-sm">
      {all ? (
        <div className="px-5 pb-4 pt-4">
          <div className="mb-2 flex flex-wrap items-end justify-between gap-3">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-[0.14em] myc-muted">GSQ manufacturing network</p>
              <h2 className="text-xl font-black">All 18 sites</h2>
            </div>
            <div className="flex flex-wrap gap-3 text-[10px] font-bold">
              {regionOrder.map((region: string) => (
                <span key={region} className="inline-flex items-center gap-1.5">
                  <i className="inline-block size-2 rounded-full" style={{ background: regionColor[region] }} />
                  {region}
                </span>
              ))}
            </div>
          </div>
          <NetworkMap onSelectSite={onSelectSite} />
          <div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
            {regionOrder.map((region: string) => (
              <div key={region}>
                <p className="mb-1 text-[10px] font-black uppercase tracking-wider myc-muted">{region}</p>
                <div className="flex flex-wrap gap-1.5">
                  {geoSites.filter((item: GeoSite) => item.region === region).map((item: GeoSite) => (
                    <button
                      key={item.code}
                      type="button"
                      onClick={() => onSelectSite(item.code)}
                      className="rounded-full border bg-background px-2.5 py-1 text-[10px] font-bold hover:border-[var(--takeda-red)]"
                    >
                      {item.code} · {item.name}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : current ? (
        <SiteGeoPicture site={current} onSelectSite={onSelectSite} />
      ) : (
        <div className="px-5 py-6"><h2 className="text-xl font-black">{site.name}</h2></div>
      )}
    </section>
  );
}
